// Model Router — accept a prompt or an OpenAI-style messages array.
const j = $json.body || $json;
let prompt = j.prompt || j.message || j.text || j.input || '';
if (!prompt && Array.isArray(j.messages)) prompt = j.messages.map((m) => String(m && m.content || '')).join('\n');
prompt = String(prompt || '').trim();
return [{ json: { prompt, requested_model: j.model || null, source: j.source || 'api' } }];

// Model Router — extract Gemini text.
const raw = $json || {};
let text = '';
try {
  text = ((raw.candidates && raw.candidates[0] && raw.candidates[0].content && raw.candidates[0].content.parts) || [])
    .map((p) => p.text || '').join('').trim();
} catch (e) { text = ''; }
if (text.length > 8000) text = text.slice(0, 7990) + '…';
return [{ json: { ok: true, model: 'google/gemini-3.5-flash-lite', text, fallback: false } }];

// Model Router — log a model failure to Supabase, then pass the prompt + reason onward.
const src = $input.first().json || {};
const e = src.error || src;
let reason = '';
if (typeof e === 'string') reason = e;
else if (e && typeof e === 'object') reason = [e.message, e.description, e.code, e.status].filter(Boolean).join(' — ');
if (!reason) reason = JSON.stringify(e || {}).slice(0, 800);
const base = String($env.SUPABASE_URL || '').replace(/\/+$/, '');
const key = String($env.SUPABASE_SERVICE_KEY || '');
const prompt = $('Normalize Request').first().json.prompt;
if (base && key) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/rest/v1/model_fallback_log',
      headers: { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: { model: 'google/gemini-3.5-flash-lite', reason: String(reason).slice(0, 1000) },
      json: true,
      timeout: 15000,
    });
  } catch (err) {}
}
return [{ json: { prompt, reason: String(reason).slice(0, 1000), from: 'primary' } }];

